import json
import pandas as pd
import numpy as np

FIELD_MAP = {
    'source_a': {
        'id': 'user_id', 'user_id': 'user_id', 'userId': 'user_id',
        'full_name': 'name', 'name': 'name', 'userName': 'name',
        'email': 'email', 'email_address': 'email',
        'registration_date': 'created_date', 'created_at': 'created_date', 'joined': 'created_date',
        'status': 'status', 'is_active': 'status', 'active': 'status',
    },
    'source_b': {
        'user_id': 'user_id', 'id': 'user_id', 'userId': 'user_id',
        'name': 'name', 'full_name': 'name', 'userName': 'name',
        'email_address': 'email', 'email': 'email',
        'created_at': 'created_date', 'registration_date': 'created_date', 'joined': 'created_date',
        'is_active': 'status', 'status': 'status', 'active': 'status',
    },
    'source_c': {
        'userId': 'user_id', 'user_id': 'user_id', 'id': 'user_id',
        'userName': 'name', 'full_name': 'name', 'name': 'name',
        'email': 'email', 'email_address': 'email',
        'joined': 'created_date', 'registration_date': 'created_date', 'created_at': 'created_date',
        'active': 'status', 'is_active': 'status', 'status': 'status',
    },
}

CANONICAL_FIELDS = ['user_id', 'name', 'email', 'created_date', 'status']
SOURCES = ['source_a', 'source_b', 'source_c']
PRIORITY = ['source_a', 'source_b', 'source_c']


def normalize_status(value, source):
    if value is None or (isinstance(value, float) and np.isnan(value)):
        return None
    if isinstance(value, bool):
        return 'active' if value else 'inactive'
    s = str(value).strip().lower()
    if s in ('true', 'false'):
        return 'active' if s == 'true' else 'inactive'
    if s in ('active', 'inactive', '1', '0', 'yes', 'no'):
        return 'active' if s in ('active', 'true', '1', 'yes') else 'inactive'
    return str(value).strip()


def normalize_date(value):
    if value is None or (isinstance(value, float) and np.isnan(value)):
        return None
    s = str(value).strip()
    if not s:
        return None
    ts = pd.to_datetime(s, errors='coerce')
    if pd.isna(ts):
        return s
    return ts.strftime('%Y-%m-%d')


def normalize_email(value):
    if value is None or (isinstance(value, float) and np.isnan(value)):
        return None
    return str(value).strip()


def normalize_name(value):
    if value is None or (isinstance(value, float) and np.isnan(value)):
        return None
    return str(value).strip()


def coerce_user_id(value):
    if value is None or (isinstance(value, float) and np.isna(value)):
        return None
    try:
        return int(value)
    except (ValueError, TypeError):
        return None


def load_source(source):
    if source == 'source_a':
        with open('/data/source_a/users.json') as f:
            raw = json.load(f)
        return pd.DataFrame(raw)
    if source == 'source_b':
        return pd.read_csv('/data/source_b/users.csv')
    if source == 'source_c':
        return pd.read_parquet('/data/source_c/users.parquet')
    raise ValueError(source)


def canonicalize(df, source):
    mapping = FIELD_MAP[source]
    rename = {}
    for col in df.columns:
        if col in mapping:
            rename[col] = mapping[col]
    df = df.rename(columns=rename)
    keep = [c for c in df.columns if c in CANONICAL_FIELDS]
    df = df[keep].copy()

    if 'user_id' in df.columns:
        df['user_id'] = df['user_id'].apply(coerce_user_id)
    else:
        return pd.DataFrame(columns=CANONICAL_FIELDS + ['__source'])

    df['name'] = df['name'].apply(normalize_name) if 'name' in df.columns else None
    df['email'] = df['email'].apply(normalize_email) if 'email' in df.columns else None
    df['created_date'] = df['created_date'].apply(normalize_date) if 'created_date' in df.columns else None
    if 'status' in df.columns:
        df['status'] = df['status'].apply(lambda v: normalize_status(v, source))
    df['__source'] = source
    df = df.dropna(subset=['user_id'])
    df['user_id'] = df['user_id'].astype(int)
    return df


def build_records():
    records = {}
    for source in SOURCES:
        df = load_source(source)
        df = canonicalize(df, source)
        for _, row in df.iterrows():
            uid = int(row['user_id'])
            entry = records.setdefault(uid, {})
            for field in CANONICAL_FIELDS:
                if field in df.columns and field != 'user_id':
                    val = row[field]
                    if val is not None and not (isinstance(val, float) and np.isnan(val)):
                        entry[(source, field)] = val
    return records


def detect_conflicts(records):
    conflicts = []
    for uid in sorted(records.keys()):
        fields_present = records[uid]
        for field in [f for f in CANONICAL_FIELDS if f != 'user_id']:
            per_source = {s: fields_present.get((s, field)) for s in SOURCES}
            present = {s: v for s, v in per_source.items() if v is not None}
            if len(present) < 2:
                continue
            values = list({v for v in present.values()})
            if len(values) > 1:
                selected = None
                for s in PRIORITY:
                    if per_source[s] is not None:
                        selected = per_source[s]
                        break
                conflicts.append({
                    'user_id': uid,
                    'field': field,
                    'values': {s: per_source[s] for s in SOURCES},
                    'selected': selected,
                })
    return conflicts


def build_merged(records):
    rows = []
    for uid in sorted(records.keys()):
        fields_present = records[uid]
        row = {'user_id': int(uid)}
        for field in [f for f in CANONICAL_FIELDS if f != 'user_id']:
            chosen = None
            for s in PRIORITY:
                v = fields_present.get((s, field))
                if v is not None:
                    chosen = v
                    break
            row[field] = chosen
        rows.append(row)
    df = pd.DataFrame(rows, columns=CANONICAL_FIELDS)
    df['user_id'] = df['user_id'].astype('int64')
    for col in ['name', 'email', 'created_date']:
        df[col] = df[col].astype('string')
    df['status'] = df['status'].astype('string')
    return df


def main():
    records = build_records()
    conflicts = detect_conflicts(records)
    merged = build_merged(records)

    merged.to_parquet('/app/merged_users.parquet', index=False)

    report = {
        'total_conflicts': len(conflicts),
        'conflicts': conflicts,
    }
    with open('/app/conflicts.json', 'w') as f:
        json.dump(report, f, indent=2)

    print(f"Merged {len(merged)} users")
    print(f"Found {len(conflicts)} conflicts")
    print()
    print(merged.to_string(index=False))
    print()
    print(json.dumps(report, indent=2))


if __name__ == '__main__':
    main()

